#include "Tournament/TournamentMatch.h"
TournamentMatch::TournamentMatch():round_(0){} TournamentMatch::TournamentMatch(const std::string&id,const std::string&t,const std::string&h,const std::string&a,int round,const std::string&date,const std::string&time):match_id_(id),tournament_id_(t),home_team_id_(h),away_team_id_(a),date_(date),start_time_(time),round_(round){} const std::string& TournamentMatch::getMatchId()const{return match_id_;} const std::string& TournamentMatch::getTournamentId()const{return tournament_id_;} const std::string& TournamentMatch::getHomeTeamId()const{return home_team_id_;} const std::string& TournamentMatch::getAwayTeamId()const{return away_team_id_;} int TournamentMatch::getRound()const{return round_;} const std::string& TournamentMatch::getDate()const{return date_;} const std::string& TournamentMatch::getStartTime()const{return start_time_;}
